-- ntf.outbox_messages: Events written in the business transaction; the dispatcher publishes them (spec 03 section 7.5)
create table if not exists ntf.outbox_messages (
    id uuid not null,
    occurred_at timestamptz not null,
    event_type text not null,
    aggregate_type text not null,
    aggregate_id uuid not null,
    payload jsonb not null,
    headers jsonb not null default '{}'::jsonb,
    published_at timestamptz,
    constraint pk_outbox_messages primary key (id)
);
create index if not exists ix_outbox_messages_occurred_at_unpublished on ntf.outbox_messages (occurred_at) where (published_at is null); -- dispatcher reads unpublished messages in order

-- ntf.preferences: Preferences [KRN-NTF-04, HRM-NTF-04]
create table if not exists ntf.preferences (
    user_id uuid not null,
    event_group text not null,
    channel text not null,
    enabled boolean not null default false,
    quiet_hours jsonb,
    constraint pk_preferences primary key (user_id, event_group, channel),
    constraint ck_preferences_event_group_code check (length(event_group) between 1 and 40 and event_group = btrim(event_group))
);

-- ntf.subscriptions: Subscriptions [KRN-NTF-03]
